result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "census.py", "content": "#!/usr/bin/env python3
"""ADT census reconciler — data-quality tooling for synthetic hospital event logs.

Input: JSONL event log, one JSON object per line:
    {"patient": "P01", "event": "admit"|"discharge", "ts": "<ISO datetime>"}

Produces:
  (a) a census timeline: for any requested snapshot instant, the set of
      patients admitted at that instant (based on valid stays only), and
  (b) a data-quality report detecting:
        - discharge_without_admit   : discharge with no open admit to match
        - double_admit             : admit while a prior admit is still open
        - discharge_before_admit   : paired discharge timestamp precedes its admit
        - open_stay                : still admitted at end of log (informational)

Reconciliation is order-invariant: events are grouped per patient and matched
by pairing the i-th earliest admit with the i-th earliest discharge, so
shuffled input yields identical results.

CLI:
    census.py log.jsonl --at 2024-05-01T12:00     # census count + patient ids
    census.py log.jsonl --at 2024-05-01T12:00 --report   # also print DQ report
"""

from __future__ import annotations

import argparse
import json
import sys
from collections import defaultdict
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path
from typing import Iterable, Optional

ERROR_KINDS = ("discharge_without_admit", "double_admit", "discharge_before_admit")
INFO_KINDS = ("open_stay",)


@dataclass(frozen=True)
class Event:
    """One ADT event row."""
    patient: str
    event: str
    ts: datetime
    seq: int  # arrival order in the log (tie-breaker only)


@dataclass(frozen=True)
class Finding:
    """One data-quality finding."""
    kind: str
    patient: str
    ts: Optional[datetime]
    detail: str


@dataclass(frozen=True)
class Stay:
    """A reconciled admission interval."""
    patient: str
    admit_ts: datetime
    discharge_ts: Optional[datetime]  # None => still open at end of log


@dataclass(frozen=True)
class Reconciliation:
    stays: tuple[Stay, ...]
    open_stays: tuple[Stay, ...]
    findings: tuple[Finding, ...]

    @property
    def errors(self) -> tuple[Finding, ...]:
        return tuple(f for f in self.findings if f.kind in ERROR_KINDS)

    @property
    def infos(self) -> tuple[Finding, ...]:
        return tuple(f for f in self.findings if f.kind in INFO_KINDS)

    def census_at(self, instant: datetime) -> frozenset[str]:
        """Patients occupying a bed at `instant`, counting valid stays only.

        Error rows (all four kinds except open_stay, which is informational)
        never contribute to the census.
        """
        admitted = set()
        for s in self.stays:
            if s.admit_ts <= instant < s.discharge_ts:
                admitted.add(s.patient)
        for s in self.open_stays:
            if s.admit_ts <= instant:
                admitted.add(s.patient)
        return frozenset(admitted)


def _order_key(ev: Event) -> tuple:
    return (ev.ts, ev.seq)


def reconcile(events: Iterable[Event]) -> Reconciliation:
    by_patient: dict[str, dict[str, list[Event]]] = defaultdict(
        lambda: {"admits": [], "discharges": []}
    )
    for ev in events:
        if ev.event not in ("admit", "discharge"):
            raise ValueError(f"unknown event type {ev.event!r} (seq {ev.seq})")
        by_patient[ev.patient]["admits" if ev.event == "admit" else "discharges"].append(ev)

    stays: list[Stay] = []
    open_stays: list[Stay] = []
    findings: list[Finding] = []

    for patient in sorted(by_patient):
        admits = sorted(by_patient[patient]["admits"], key=_order_key)
        discharges = sorted(by_patient[patient]["discharges"], key=_order_key)

        # Pair the i-th earliest admit with the i-th earliest discharge.
        n_pairs = min(len(admits), len(discharges))
        for i in range(n_pairs):
            a, d = admits[i], discharges[i]
            if d.ts < a.ts:
                findings.append(Finding(
                    "discharge_before_admit", patient, d.ts,
                    f"discharge {d.ts.isoformat()} precedes matching admit "
                    f"{a.ts.isoformat()}; both rows excluded from census",
                ))
            else:
                stays.append(Stay(patient, a.ts, d.ts))

        # Surplus discharges: nothing open to match against.
        for d in discharges[n_pairs:]:
            findings.append(Finding(
                "discharge_without_admit", patient, d.ts,
                f"discharge {d.ts.isoformat()} with no prior open admit",
            ))

        # Surplus admits: open stays if the patient was never discharged,
        # otherwise duplicated admits during an existing stay.
        for a in admits[n_pairs:]:
            if not discharges:
                open_stays.append(Stay(patient, a.ts, None))
                findings.append(Finding(
                    "open_stay", patient, a.ts,
                    f"admitted {a.ts.isoformat()}, still admitted at end of log",
                ))
            else:
                findings.append(Finding(
                    "double_admit", patient, a.ts,
                    f"admit {a.ts.isoformat()} while a prior admit was still open",
                ))

    def fk(f: Finding) -> tuple:
        return (f.kind, f.patient, f.ts or datetime.min)

    findings.sort(key=fk)
    return Reconciliation(tuple(stays), tuple(open_stays), tuple(findings))


def parse_log(path: str | Path) -> list[Event]:
    events: list[Event] = []
    with open(path, encoding="utf-8") as fh:
        for seq, line in enumerate(fh):
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            events.append(Event(
                patient=str(rec["patient"]),
                event=str(rec["event"]),
                ts=datetime.fromisoformat(rec["ts"]),
                seq=seq,
            ))
    return events


def main(argv: Optional[list[str]] = None) -> int:
    ap = argparse.ArgumentParser(description="ADT census reconciler")
    ap.add_argument("log", help="event log (.jsonl)")
    ap.add_argument("--at", required=True, help="snapshot instant, ISO datetime")
    ap.add_argument("--report", action="store_true",
                    help="also print the data-quality report")
    args = ap.parse_args(argv)

    recon = reconcile(parse_log(args.log))
    instant = datetime.fromisoformat(args.at)
    admitted = sorted(recon.census_at(instant))

    print(f"{instant.isoformat()}: {len(admitted)} admitted")
    for pid in admitted:
        print(f"  {pid}")

    if args.report:
        errors = recon.errors
        print(f"\ndata-quality report: {len(errors)} error(s), "
              f"{len(recon.infros) if False else len(recon.infos)} informational")
        for f in recon.findings:
            tag = "INFO" if f.kind in INFO_KINDS else "ERROR"
            print(f"  [{tag}] {f.kind}: patient={f.patient} ts="
                  f"{f.ts.isoformat() if f.ts else '-'} ({f.detail})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
